opacity:0;transition:opacity .08s}.hit-marker.show{opacity:1}.damage-flash{position:absolute;inset:0;opacity:0;background:radial-gradient(ellipse,transparent 28%,rgba(158,45,30,.28) 100%);transition:opacity .15s}.damage-flash.show{opacity:1}.bottom-hud{position:absolute;bottom:0;left:0;width:100%;padding:0 4.2% max(25px,env(safe-area-inset-bottom));height:126px;display:flex;align-items:flex-end;justify-content:space-between;background:linear-gradient(0deg,rgba(7,11,9,.88),rgba(7,11,9,.05))}.vitals{display:flex;align-items:center;gap:11px;width:210px;padding-bottom:7px}.health-emblem{width:28px;height:28px;display:grid;place-items:center;border:1px solid rgba(192,204,182,.47);color:#bfceae;font-size:22px;font-weight:500}.health-copy{display:flex;flex-direction:column;min-width:35px}.health-copy small{font-size:8px}.health-copy b{font:18px 'DM Mono',monospace;color:#e3e9dc}.health-track{width:94px;height:3px;background:rgba(220,230,212,.23);margin-left:3px}.health-track i{height:100%;display:block;width:100%;background:#a6be81;transition:width .25s,background .25s}.controls-hint{position:absolute;left:50%;transform:translateX(-50%);bottom:33px;color:#a9b0a5;font:8px 'DM Mono',monospace;letter-spacing:1px;white-space:nowrap}.controls-hint span{color:#e0e5d9;border:1px solid rgba(225,229,218,.35);padding:3px 5px;margin:0 3px}.controls-hint i{font-style:normal;color:#c4aa65;padding:0 5px}.weapon-info{height:72px;display:flex;align-items:center;gap:19px;border-left:1px solid rgba(220,225,212,.25);padding-left:21px;position:relative}.weapon-name{display:flex;flex-direction:column;gap:3px}.weapon-name>small{font-size:8px}.weapon-name>b{font-size:23px;letter-spacing:1px;line-height:1}.weapon-name>b span{font-size:12px;color:#c0c6b8;letter-spacing:1px}.weapon-mode{font:8px 'DM Mono',monospace;color:#abb3a5;letter-spacing:.5px}.weapon-mode i{width:5px;height:5px;margin-right:4px}.weapon-mode b{color:#b6a36d;font-weight:400}.ammo{display:flex;align-items:baseline;gap:5px;padding-right:44px}.ammo strong{font:38px 'DM Mono',monospace;letter-spacing:-3px}.ammo span{font:14px 'DM Mono',monospace;color:#889185}.ammo>b{font:15px 'DM Mono',monospace;color:#9da597}.ammo small{position:absolute;right:47px;bottom:2px;font:7px 'DM Mono',monospace;letter-spacing:1.4px;color:#8f998b}.weapon-silhouette{font-size:38px;color:#a4a995;transform:rotate(-25deg);opacity:.62;margin-left:-27px}.toast{position:absolute;left:50%;top:67%;transform:translate(-50%,10px);font:10px 'DM Mono',monospace;letter-spacing:1.3px;color:#d8c27d;opacity:0;transition:all .3s}.toast.show{opacity:1;transform:translate(-50%,0)}.reload-indicator{position:absolute;left:50%;top:58%;transform:translateX(-50%);font:9px 'DM Mono',monospace;letter-spacing:2px;color:#e5ddc8;opacity:0}.reload-indicator.show{opacity:1}.reload-indicator i{display:block;width:80px;height:2px;background:#cbb675;margin:7px auto;animation:reloadbar 1.2s linear}@keyframes reloadbar{from{width:0}to{width:80px}}.mobile-controls{display:none;pointer-events:none}.screen{position:absolute;inset:0;z-index:5;background:linear-gradient(90deg,rgba(8,12,10,.88) 0%,rgba(8,12,10,.65) 43%,rgba(8,12,10,.08) 100%);display:flex;align-items:center;padding:5.8% 8.3%;transition:opacity .45s,visibility .45s}.screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-screen:after{content:'';position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(8,12,10,.28),transparent 90%)}.intro-top{position:absolute;top:7%;left:8.3%;right:8.3%;display:flex;align-items:center;justify-content:space-between}.brand-lockup{display:flex;align-items:center;gap:11px;font-size:15px;line-height:.81;letter-spacing:2.8px;font-weight:600}.brand-lockup b{color:#d2bb7d}.brand-symbol{width:37px;height:37px;font-size:26px}.edition{font:9px 'DM Mono',monospace;color:#b8c0b3;letter-spacing:1.4px}.edition i,.intro-footer i,.pause-panel small i{color:#ccaf65;font-style:normal}.intro-copy{width:min(490px,54vw);margin-top:25px}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:1.7px;color:#d4be80}.eyebrow i{display:inline-block;width:17px;height:1px;background:#d4be80;vertical-align:middle;margin-right:8px}.intro-copy h1,.pause-panel h2,.result-panel h2{font-size:clamp(61px,8.2vw,112px);font-weight:800;letter-spacing:-2px;line-height:.78;margin:21px 0 18px}.intro-copy h1 em,.pause-panel h2 em,.result-panel h2 em{font-style:normal;color:#d2bd84}.intro-copy>p{font-size:16px;line-height:1.35;color:#cad0c3;letter-spacing:.3px;margin:0 0 25px}.briefing{border-top:1px solid rgba(213,222,205,.24);padding-top:12px;max-width:435px}.briefing>span{font:8px 'DM Mono',monospace;letter-spacing:1.4px;color:#d3bc7d}.briefing p{font-size:13px;line-height:1.4;color:#c2c9bc;max-width:410px;margin:8px 0 14px}.briefing-meta{display:flex;gap:36px;font:8px 'DM Mono',monospace;letter-spacing:.5px;color:#d4dbcf}.briefing-meta span{display:flex;flex-direction:column;gap:4px}.briefing-meta b{font-size:7px;color:#7f8a7e;font-weight:400;letter-spacing:1px}.briefing-meta i{font-style:normal;color:#cead65}.deploy-button{margin-top:25px;width:215px;height:49px;display:flex;align-items:center;justify-content:space-between;padding:0 15px 0 18px;background:#d0bb7d;color:#181b15;border:0;cursor:pointer;letter-spacing:2px;font-weight:800;font-size:13px;clip-path:polygon(0 0,100% 0,100% 76%,92% 100%,0 100%);transition:background .2s,transform .2s}.deploy-button:hover{background:#e8d493;transform:translateY(-2px)}.deploy-button b{font-size:20px;font-weight:500}.input-note{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#899386;margin-top:12px}.input-note i{color:#cfb675;font-style:normal;padding:0 5px}.intro-side{position:absolute;right:8.4%;top:36%;height:250px;display:flex;flex-direction:column;align-items:center;gap:18px;color:#c2cbbd;font:9px 'DM Mono',monospace}.side-line{height:172px;width:1px;background:linear-gradient(#ceb87c 0 25%,rgba(210,220,203,.22) 25% 100%)}.side-caption{position:absolute;top:270px;right:0;text-align:right;white-space:nowrap;line-height:1.55;color:#a7afa1;letter-spacing:1px}.intro-footer{position:absolute;left:8.3%;right:8.3%;bottom:4%;display:flex;justify-content:space-between;color:#7e887d;font:7px 'DM Mono',monospace;letter-spacing:1.2px}.pause-screen,.result-screen{justify-content:center;text-align:center;padding:0;background:rgba(6,10,8,.78);backdrop-filter:blur(8px)}.pause-panel,.result-panel{width:min(500px,90vw);border-top:1px solid rgba(210,189,132,.6);padding:35px 20px 30px;background:linear-gradient(180deg,rgba(20,27,22,.95),rgba(12,17,14,.91));box-shadow:0 24px 80px #0008}.pause-panel h2,.result-panel h2{font-size:76px;margin:20px 0 15px}.pause-panel p,.result-panel p{color:#b8c0b3;font-size:15px;line-height:1.5}.pause-panel .deploy-button,.result-panel .deploy-button{margin:24px auto 0}.pause-panel small{display:block;margin-top:16px;font:8px 'DM Mono',monospace;letter-spacing:1.1px;color:#8b9589}.result-stats{display:flex;justify-content:center;gap:28px;margin-top:25px;font:8px 'DM Mono',monospace;color:#9ba496;letter-spacing:1px}.result-stats span{display:flex;flex-direction:column;gap:5px}.result-stats b{font:18px 'DM Mono',monospace;color:#dfd3a9}.loading-screen{position:absolute;inset:0;z-index:10;background:#111713;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;transition:opacity .6s}.loading-screen.done{opacity:0;pointer-events:none}.loading-mark{width:42px;height:42px;border:1px solid #cdb879;color:#d4bf83;display:grid;place-items:center;font-size:28px;font-weight:800}.loading-screen>span{font:8px 'DM Mono',monospace;letter-spacing:1.7px;color:#939e8f}.loading-screen>i{width:140px;height:1px;background:#343d34}.loading-screen>i b{display:block;width:38%;height:100%;background:#cbb777;animation:load 1.3s ease-in-out infinite}@keyframes load{from{transform:translateX(-100%)}to{transform:translateX(370%)}}
