uto;border:1px solid rgba(228,224,201,.48);background:rgba(23,29,23,.4);touch-action:none}.fire-button{right:7%;bottom:max(130px,calc(env(safe-area-inset-bottom) + 122px));width:71px;height:71px;border-radius:50%;display:grid;place-items:center;color:#e0d39f}.fire-button span{font:8px 'DM Mono',monospace;letter-spacing:1px}.fire-button i{position:absolute;font-size:25px;font-style:normal;opacity:.38}.reload-button{right:20%;bottom:max(125px,calc(env(safe-area-inset-bottom) + 117px));width:39px;height:39px;border-radius:50%;font-size:21px;color:#e2e1d3;display:grid;place-items:center}.reload-button small{position:absolute;top:42px;font:6px 'DM Mono',monospace;letter-spacing:.5px;white-space:nowrap}.screen{padding:0 7%}.intro-screen{align-items:flex-start;padding-top:100px;background:linear-gradient(90deg,rgba(8,12,10,.83),rgba(8,12,10,.56) 72%,rgba(8,12,10,.12))}.intro-top{top:24px;left:7%;right:7%}.brand-lockup{font-size:12px}.brand-symbol{width:30px;height:30px;font-size:21px}.edition{font-size:6px;letter-spacing:.6px}.intro-copy{width:100%;margin-top:0}.eyebrow{font-size:7px;letter-spacing:1px}.intro-copy h1{font-size:clamp(64px,18vw,91px);margin:17px 0 14px}.intro-copy>p{font-size:13px;margin-bottom:17px}.briefing{max-width:390px}.briefing p{font-size:11px;margin:7px 0 10px}.briefing-meta{gap:20px;font-size:7px}.deploy-button{width:184px;height:43px;margin-top:18px;font-size:11px}.input-note{font-size:6px}.intro-side{right:5%;top:34%;opacity:.72}.side-caption{display:none}.intro-footer{left:7%;right:7%;bottom:2%;font-size:6px}.pause-panel h2,.result-panel h2{font-size:64px}.threat-label{top:44%}.toast{top:62%}.reload-indicator{top:55%}}
